/// that lowering a limit deletes nothing and names the fixed technical limits that stay.
/// </summary>
internal static class StorageLimitsCatalog
{
    internal static readonly (string Key, string English, string German)[] Entries =
    {
        ("budgets.group.lists", "Favorites, ratings, bookmarks, groups and source watches", "Favoriten, Bewertungen, Lesezeichen, Gruppen und Quellenbeobachtungen"),
        ("budgets.group.previews", "Previews and export", "Vorschauen und Export"),
        ("budgets.group.import", "Import", "Import"),
        ("budgets.favoriteEntries", "Favorites and ratings: entries per list", "Favoriten und Bewertungen: Einträge je Liste"),
        ("budgets.favoriteEntriesHint", "How many entries each of the three lists (favorite media, favorite threads, ratings) may hold. Allowed: 10000 to 500000.", "Wie viele Einträge jede der drei Listen (Favoriten bei Medien, Favoriten bei Threads, Bewertungen) aufnehmen darf. Erlaubt: 10000 bis 500000."),
        ("budgets.favoriteFile", "Favorites and ratings: file size (MiB)", "Favoriten und Bewertungen: Dateigröße (MiB)"),
        ("budgets.favoriteFileHint", "Size limit of each of the three list files. A change that would make a file larger than this is refused; removing entries always works. If you raise the entry limit a lot, raise this one too. Allowed: 1 to 128 MiB.", "Größengrenze jeder der drei Listendateien. Eine Änderung, die eine Datei über diese Größe wachsen ließe, wird abgelehnt; Einträge entfernen geht immer. Wenn du die Eintragsgrenze stark erhöhst, erhöhe auch diese. Erlaubt: 1 bis 128 MiB."),
        ("budgets.postBookmarks", "Post bookmarks", "Post-Lesezeichen"),
        ("budgets.postBookmarksHint", "How many posts can carry a bookmark. The note length (8000 characters, counted as Unicode code points; an emoji can count as several) and the file size (32 MiB) are fixed technical limits. Allowed: 1000 to 100000.", "Wie viele Posts ein Lesezeichen tragen können. Die Länge einer Notiz (8000 Zeichen, gezählt als Unicode-Codepoints; ein Emoji kann mehrere zählen) und die Dateigröße (32 MiB) sind feste technische Grenzen. Erlaubt: 1000 bis 100000."),
        ("budgets.savedSearches", "Saved searches", "Gespeicherte Suchen"),
