        ("budgets.importCatalogMiB", "Import: catalog file size (MiB)", "Import: Größe der Katalogdatei (MiB)"),
        ("budgets.importCatalogMiBHint", "Size limit of the file that lists every imported file. A new import that would make it larger is refused. The catalog stays readable. Allowed: 1 to 128 MiB.", "Größengrenze der Datei, die alle importierten Dateien auflistet. Ein neuer Import, der sie vergrößern würde, wird abgelehnt. Der Katalog bleibt lesbar. Erlaubt: 1 bis 128 MiB."),
        ("budgets.importTags", "Import: tags per batch", "Import: Tags je Stapel"),
