        ("limit.favoriteEntries", "This list has reached its limit of {0} entries, so nothing new can be added. Raise “{1}” under {2}; existing entries are not affected.", "Diese Liste hat ihre Grenze von {0} Einträgen erreicht, es kann nichts Neues hinzukommen. Erhöhe „{1}“ unter {2}; vorhandene Einträge bleiben unberührt."),
        ("limit.favoriteFile", "This list file has reached its size limit of {0}, so nothing new can be added. Raise “{1}” under {2}; removing entries still works.", "Die Datei dieser Liste hat ihre Größengrenze von {0} erreicht, es kann nichts Neues hinzukommen. Erhöhe „{1}“ unter {2}; Einträge entfernen geht weiterhin."),
        ("limit.postBookmarks", "The limit of {0} post bookmarks is reached. Raise “{1}” under {2}; existing bookmarks and notes are kept.", "Die Grenze von {0} Post-Lesezeichen ist erreicht. Erhöhe „{1}“ unter {2}; vorhandene Lesezeichen und Notizen bleiben erhalten."),
